// group B.  Mean/variance computed via sub-warp shuffles with mask.
// -----------------------------------------------------------------------
__global__ void __launch_bounds__(WARP16_BLOCK, 4)
fused_gn_min_warp16_kernel(
    const float* __restrict__ x,
    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    float* __restrict__ min_out,
    const int N,
    const int C,
    const int num_groups,  // expected 512
