    const int n = blockIdx.x;
    if (n >= N) return;

    const int tid     = threadIdx.x;
    const int warp_id = tid / WARP_SIZE;          // 0..7
    const int lane_id = tid % WARP_SIZE;          // 0..31

    // Each lane belongs to one half-warp sub-partition.
    // Sub-partition mask: lower 16 lanes or upper 16 lanes.
    const int sub_id   = lane_id >> 4;            // 0 (lanes 0-15) or 1 (lanes 16-31)
    const int sub_lane = lane_id & 15;            // 0..15 within the sub-partition
    const uint32_t sub_mask = (sub_id == 0) ? 0x0000FFFFu : 0xFFFF0000u;

    const float* x_row = x + (long)n * C;

    // Number of group-pairs per warp (each warp handles 2 groups per iter).
    // Total warps per block = WARP16_BLOCK / 32.
    const int warps_per_block = WARP16_BLOCK / WARP_SIZE;  // 8
    // Each warp processes pairs of groups with stride = warps_per_block.
    // group pair index owned by this warp in this iteration:
    //   pair = warp_id + iter * warps_per_block
    // group index = pair * 2 + sub_id

    float warp_min = FLT_MAX;

    for (int pair = warp_id; pair * 2 + 1 < num_groups; pair += warps_per_block) {
        const int g = pair * 2 + sub_id;   // group index for this sub-partition
        const int g_start = g * 16;        // group_size == 16

        // Each lane loads one element from its group.
        const float val = x_row[g_start + sub_lane];

        // --- mean via sub-warp reduction ---
        float sum = val;
        sum += __shfl_xor_sync(sub_mask, sum, 8);
        sum += __shfl_xor_sync(sub_mask, sum, 4);
        sum += __shfl_xor_sync(sub_mask, sum, 2);
        sum += __shfl_xor_sync(sub_mask, sum, 1);
        const float mean = sum * (1.0f / 16.0f);

