        const float diff = val - mean;
        float sq = diff * diff;
        sq += __shfl_xor_sync(sub_mask, sq, 8);
        sq += __shfl_xor_sync(sub_mask, sq, 4);
        sq += __shfl_xor_sync(sub_mask, sq, 2);
        sq += __shfl_xor_sync(sub_mask, sq, 1);
        const float inv_std = rsqrtf(sq * (1.0f / 16.0f) + eps);

