        sub_min = fminf(sub_min, __shfl_xor_sync(sub_mask, sub_min, 8));
        sub_min = fminf(sub_min, __shfl_xor_sync(sub_mask, sub_min, 4));
        sub_min = fminf(sub_min, __shfl_xor_sync(sub_mask, sub_min, 2));
        sub_min = fminf(sub_min, __shfl_xor_sync(sub_mask, sub_min, 1));

