        if (lane_id == 0) warp_min = fminf(warp_min, other);
    }

    // Accumulate warp minimums in shared memory.
    __shared__ float warp_mins[8];  // one per warp (8 warps in a 256-thread block)
    if (lane_id == 0) {
        warp_mins[warp_id] = warp_min;
    }
    __syncthreads();

