    float local_min = FLT_MAX;

    for (int g_base = tid; g_base < num_groups; g_base += blockDim.x) {
        const int g_start = g_base * group_size;
        float mean = 0.f, m2 = 0.f;
        for (int k = 0; k < group_size; ++k) {
            float v = x_row[g_start + k];
            float delta = v - mean;
            mean += delta / (k + 1);
            float delta2 = v - mean;
            m2 += delta * delta2;
        }
        float inv_std = rsqrtf(m2 / group_size + eps);
        for (int k = 0; k < group_size; ++k) {
            int c = g_start + k;
            float normed = (x_row[c] - mean) * inv_std;
            float val = normed * gn_weight[c] + gn_bias[c];
            if (val < local_min) local_min = val;
        }
    }

    float warp_min = warp_reduce_min(local_min);

    __shared__ float warp_mins_g[4];
    if (lane_id == 0) warp_mins_g[warp_id] = warp_min;
    __syncthreads();

    if (warp_id == 0) {
        float block_min = (lane_id < 4) ? warp_mins_g[lane_id] : FLT_MAX;
        block_min = warp_reduce_min(block_min);
        if (lane_id == 0) min_out[n] = block_min;
    }
}

